});

test('invoiceTotals bulk discount applies at exactly 10 qty', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
