  });
  const invoice = invoiceResult.value;
  const totalsWithoutVoucher = invoiceTotals(invoice);

  const voucherResult = applyVoucher(invoice, { code: 'MEGA', amount: totalsWithoutVoucher.total + 1000 });
  const totalsWithVoucher = invoiceTotals(voucherResult.value);

  assert.equal(totalsWithVoucher.total, 0);
});

test('invoiceTotals with voucher and discount', () => {
