    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 5 }],
  });
  const invoice = invoiceResult.value;

  const voucherResult = applyVoucher(invoice, { code: 'PROMO', amount: 1000 });
  const totals = invoiceTotals(voucherResult.value);

  assert.equal(totals.voucher, 1000);
  const expectedTotal = totals.subtotal - totals.discount + totals.vat - 1000;
  assert.equal(totals.total, Math.max(0, expectedTotal));
});

test('invoiceTotals with multiple line items and voucher', () => {
