    ],
  });
  const invoice = invoiceResult.value;

  const voucherResult = applyVoucher(invoice, { code: 'THANKS', amount: 5000 });
  const totals = invoiceTotals(voucherResult.value);

  assert.equal(totals.voucher, 5000);
  const expectedSubtotal = (5 * 8500) + (3 * 9500) + (2 * 6000);
  assert.equal(totals.subtotal, expectedSubtotal);
});

