test('applyVoucher with large voucher amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const result = applyVoucher(invoice, { code: 'MEGA', amount: 500000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.amount, 500000);
});

test('applyVoucher with various voucher codes', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = invoiceResult.value;

  const codes = ['SUMMER20', 'FALL10', 'WINTER5', 'FRIEND-REF', 'BULK25', 'VOUCHR2025'];
  for (const code of codes) {
    const result = applyVoucher(invoice, { code, amount: 1000 });
    assert.equal(result.ok, true);
    assert.equal(result.value.voucher.code, code);
  }
});

